            { key: "cpr", label: "CPA", type: "currency" },
            { key: "impressions", label: "Impresiones", type: "number" },
            { key: "clicks", label: "Clics", type: "number" },
            { key: "reach", label: "Alcance", type: "number" },
          ]}
        />
      )}
    </div>
  );
}

